import sys

def solve():
    input = sys.stdin.buffer.readline
    N = int(input())
    P = list(map(int, input().split()))

    pos = [0] * (N + 1)
    for i, x in enumerate(P, 1):
        pos[x] = i

    bit = [0] * (N + 1)

    def add(i):
        while i <= N:
            bit[i] += 1
            i += i & -i

    def sum_prefix(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0
    for v in range(1, N + 1):
        add(pos[v])
        current_pos = sum_prefix(pos[v])
        ans += (current_pos + v - 1) * (v - current_pos) // 2

    print(ans)

if __name__ == "__main__":
